#include <assert.h>

class FEMenu
{
	char released_layout[120];
};

class FEMenuEntry;

class PauseMenuSystem
{
public:
	enum {	PauseMenu,
			TimeAttackPauseMenu,
			TutorialPauseMenu,
			EndRunMenu,
			HeatMidMenu,
			HeatEndMenu,
			CompEndMenu,
			OptionsMenu,
			GoalsMenu,
			LostControllerMenu,
			SoundMenu,
			CameraMenu,
			TrickTypeMenu,
			PlaylistMenu,
			ReplayMenu,
			MapMenu,
			HighScoreMenu,
			PhotoMenu,
			TutorialMenu,
			SaveLoadMenu,
			SaveConfirmMenu,
			TipMenu,
			QuitConfirmMenu,
			NumMenus
	};

	virtual void MakeActive(int m, int sm=1);
	void EndLevel();
	void EndRun();
	void Restart();
};

class TimeAttackPauseMenuClass : public FEMenu
{
public:
	enum
	{
		Continue,
		Options,
		TrickBook,
		EndRun,
		Restart,
		Quit,
		ReturnToFE,
	};
	PauseMenuSystem* sys;
	FEMenuEntry *options;
	FEMenuEntry *trickbook;

public:
	virtual void Select(int entry_index);
};

void TimeAttackPauseMenuClass::Select(int entry_index)
{
	switch(entry_index)
	{
	case Continue:	break;
	case Options:	sys->MakeActive(PauseMenuSystem::OptionsMenu); break;
	case TrickBook:	sys->MakeActive(PauseMenuSystem::TrickTypeMenu); break;
	case EndRun :	sys->EndRun(); break;
	case Restart:	sys->Restart(); break;
	case Quit:		sys->EndLevel(); break;
	case ReturnToFE:sys->MakeActive(PauseMenuSystem::QuitConfirmMenu); break;
	default: assert(0);
	}
}
